import 'package:flutter/material.dart';
import 'package:easy_localization/easy_localization.dart';

class LanguageSelector extends StatelessWidget {
  const LanguageSelector({super.key});

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        // 현재 언어 표시
        ListTile(
          leading: const Icon(Icons.language),
          title: const Text('언어 설정'),
          subtitle: Text(_getLanguageName(context.locale)),
        ),

        const Divider(),

        // 언어 선택 라디오 버튼
        ...context.supportedLocales.map((locale) {
          return RadioListTile<Locale>(
            title: Text(_getLanguageName(locale)),
            subtitle: Text(locale.toString()),
            value: locale,
            groupValue: context.locale,
            onChanged: (Locale? value) {
              if (value != null) {
                // 언어 변경 - 자동으로 저장됨
                context.setLocale(value);
              }
            },
          );
        }),

        const SizedBox(height: 16),

        // 시스템 언어로 초기화
        TextButton.icon(
          onPressed: () {
            context.resetLocale();
          },
          icon: const Icon(Icons.refresh),
          label: const Text('시스템 언어로 초기화'),
        ),
      ],
    );
  }

  String _getLanguageName(Locale locale) {
    switch (locale.languageCode) {
      case 'ko':
        return '한국어';
      case 'en':
        return 'English';
      case 'ja':
        return '日本語';
      case 'zh':
        return '中文';
      default:
        return locale.languageCode;
    }
  }
}

// 다이얼로그로 언어 선택
void showLanguageDialog(BuildContext context) {
  showDialog(
    context: context,
    builder: (context) => AlertDialog(
      title: const Text('언어 선택'),
      content: SizedBox(
        width: double.maxFinite,
        child: ListView.builder(
          shrinkWrap: true,
          itemCount: context.supportedLocales.length,
          itemBuilder: (context, index) {
            final locale = context.supportedLocales[index];
            final isSelected = locale == context.locale;

            return ListTile(
              title: Text(
                _getLanguageNameStatic(locale),
                style: TextStyle(
                  fontWeight: isSelected ? FontWeight.bold : FontWeight.normal,
                ),
              ),
              trailing: isSelected ? const Icon(Icons.check) : null,
              onTap: () {
                context.setLocale(locale);
                Navigator.pop(context);
              },
            );
          },
        ),
      ),
    ),
  );
}

String _getLanguageNameStatic(Locale locale) {
  switch (locale.languageCode) {
    case 'ko': return '한국어';
    case 'en': return 'English';
    default: return locale.languageCode;
  }
}

