// JSON 파일에 추가할 번역들:
// {
//   "greeting": "{name}님, {time}에 오신 것을 환영합니다!",
//   "profile": {
//     "male": "{name}님의 프로필입니다. 그는 {age}살입니다.",
//     "female": "{name}님의 프로필입니다. 그녀는 {age}살입니다.",
//     "other": "{name}님의 프로필입니다. {age}살입니다."
//   },
//   "notification": {
//     "zero": "새 알림이 없습니다",
//     "one": "새 알림 1개가 있습니다",
//     "two": "새 알림 2개가 있습니다",
//     "few": "새 알림 {count}개가 있습니다",
//     "many": "새 알림 {count}개가 있습니다",
//     "other": "새 알림 {count}개가 있습니다"
//   }
// }

class AdvancedTranslations {
  // 네임드 파라미터 사용
  static String getGreeting(String name, String time) {
    return 'greeting'.tr(
      namedArgs: {
        'name': name,
        'time': time,
      },
    );
  }
  // 결과: "홍길동님, 오전 10시에 오신 것을 환영합니다!"

  // 성별 처리
  static String getProfile(String name, int age, String gender) {
    return 'profile'.tr(
      gender: gender,  // 'male', 'female', 'other'
      namedArgs: {
        'name': name,
        'age': age.toString(),
      },
    );
  }
  // 결과: "홍길동님의 프로필입니다. 그는 25살입니다."

  // 복수형 + 네임드 파라미터 조합
  static String getNotificationCount(int count) {
    return 'notification'.plural(
      count,
      namedArgs: {'count': count.toString()},
    );
  }
  // 결과 (count=5): "새 알림 5개가 있습니다"
}

