import 'package:flutter/material.dart';

class AdvancedExample extends StatelessWidget {
  const AdvancedExample({super.key});

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        // 네임드 파라미터
        Text(AdvancedTranslations.getGreeting('김철수', '오후 3시')),

        // 성별 처리
        Text(AdvancedTranslations.getProfile('이영희', 28, 'female')),

        // 복수형
        Text(AdvancedTranslations.getNotificationCount(42)),

        // 직접 사용도 가능
        Text('greeting'.tr(namedArgs: {'name': '박지민', 'time': '저녁'})),
      ],
    );
  }
}

